.jagged-sim-container {
    padding: 26px;
    min-height: 100vh;
    background:
        linear-gradient(rgba(56,189,248,0.035) 1px, transparent 1px),
        linear-gradient(90deg, rgba(56,189,248,0.035) 1px, transparent 1px),
        #0e1420;
    background-size: 36px 36px, 36px 36px, auto;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #dbe4f0;
}

.jagged-sim-header {
    position: relative;
    padding: 22px 28px 26px 28px;
    margin-bottom: 24px;
    background: linear-gradient(135deg, rgba(245,166,35,0.10), rgba(14,20,32,0));
    border: 1px solid #24314a;
    border-radius: 6px;
}
.jagged-sim-header::after {
    content: '';
    position: absolute;
    left: 0; right: 0; bottom: -1px;
    height: 7px;
    background: linear-gradient(90deg, #f5a623 0 12%, transparent 12% 16%, #f5a623 16% 33%, transparent 33% 39%, #f5a623 39% 58%, transparent 58% 61%, #f5a623 61% 82%, transparent 82% 88%, #f5a623 88% 100%);
    opacity: 0.85;
}
.jagged-sim-header h1 {
    margin: 0;
    font-size: 1.5rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #f5a623;
}
.jagged-sim-subtitle {
    margin: 6px 0 0 0;
    color: #8fa3c0;
    font-size: 0.95rem;
}

.jagged-sim-topbar { margin-bottom: 20px; }
.jagged-sim-period-counter {
    display: inline-block;
    padding: 8px 18px;
    background: #121a2b;
    border: 1px solid #2a3a58;
    border-radius: 999px;
    font-size: 0.95rem;
    color: #9fb2d0;
}
.jagged-sim-period-counter #currentDay,
.jagged-sim-period-counter #maxPeriods {
    color: #38bdf8;
    font-weight: 700;
    font-size: 1.05rem;
    padding: 0 2px;
}

.jagged-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.jagged-sim-kpi-card {
    background: #121a2b;
    border: 1px solid #24314a;
    border-left: 4px solid #38bdf8;
    border-radius: 6px;
    padding: 16px 18px;
    transition: border-color 0.2s ease;
}
.jagged-sim-kpi-card:nth-child(2) { border-left-color: #34d399; }
.jagged-sim-kpi-card:nth-child(3) { border-left-color: #f5a623; }
.jagged-sim-kpi-card:nth-child(4) { border-left-color: #a78bfa; }
.jagged-sim-kpi-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #7d90ad;
    margin-bottom: 6px;
}
.jagged-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #eef4fc;
    line-height: 1.1;
}

.jagged-sim-briefing, .jagged-sim-intel, .jagged-sim-controls, .jagged-sim-log, .jagged-sim-chart, .jagged-sim-history {
    background: #111827;
    border: 1px solid #24314a;
    border-radius: 6px;
    padding: 20px 22px;
    margin-bottom: 22px;
}
.jagged-sim-briefing h3, .jagged-sim-intel h3, .jagged-sim-controls h3, .jagged-sim-log h3 {
    margin: 0 0 12px 0;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: #38bdf8;
}
.jagged-sim-briefing #briefingText { color: #c4d2e6; line-height: 1.55; font-size: 0.95rem; }
.jagged-sim-intel { border-left: 4px solid #f5a623; }
.jagged-sim-intel h3 { color: #f5a623; }
.jagged-sim-intel #intelBox { color: #d8c9a3; font-size: 0.92rem; line-height: 1.6; }

.jagged-sim-task-grid { display: flex; flex-direction: column; gap: 10px; }
.jagged-sim-task-row, .jagged-sim-pipe-row {
    display: grid;
    grid-template-columns: 1.6fr auto 1fr auto 1fr auto;
    gap: 10px;
    align-items: center;
    background: #0e1420;
    border: 1px solid #1d2942;
    border-radius: 6px;
    padding: 10px 14px;
    transition: border-color 0.2s ease;
}
.jagged-sim-task-row:hover, .jagged-sim-pipe-row:hover { border-color: #3b527e; }
.jagged-sim-task-name { font-weight: 600; color: #eef4fc; font-size: 0.92rem; }
.jagged-sim-task-row label, .jagged-sim-pipe-row label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: #7d90ad;
    margin: 0;
}
.jagged-sim-probe {
    display: flex;
    align-items: center;
    gap: 6px;
    color: #f5a623;
    font-size: 0.8rem;
    white-space: nowrap;
}
.jagged-sim-probe input[type="checkbox"] { accent-color: #f5a623; width: 16px; height: 16px; }

.jagged-sim-controls select {
    background-color: #0b1120;
    color: #dbe4f0;
    border: 1px solid #2a3a58;
    border-radius: 4px;
    padding: 7px 10px;
    width: 100%;
    font-size: 0.88rem;
}
.jagged-sim-controls select option {
    background-color: #0b1120;
    color: #dbe4f0;
}
.jagged-sim-controls select:focus { outline: none; border-color: #38bdf8; }

.jagged-sim-pipe-grid { display: flex; flex-direction: column; gap: 10px; }
.jagged-sim-pipe-row { grid-template-columns: 1.6fr 1fr; }
.jagged-sim-pipe-esc { border-left: 4px solid #34d399; }

.jagged-sim-actions { display: flex; gap: 12px; margin-bottom: 22px; }
.jagged-sim-actions .btn {
    border-radius: 4px;
    font-weight: 600;
    padding: 10px 26px;
    transition: 0.2s ease;
}
.jagged-sim-actions #nextPeriodBtn {
    background: #f5a623;
    color: #14100a;
    border: 1px solid #f5a623;
}
.jagged-sim-actions #nextPeriodBtn:hover { background: #ffc14d; box-shadow: 0 0 14px rgba(245,166,35,0.35); }
.jagged-sim-btn-ghost {
    background: transparent;
    color: #8fa3c0;
    border: 1px solid #2a3a58;
}
.jagged-sim-btn-ghost:hover { color: #dbe4f0; border-color: #3b527e; }

.jagged-sim-log { border-left: 4px solid #ef4444; }
.jagged-sim-log h3 { color: #ef4444; }
.jagged-sim-log #eventLog { color: #c4d2e6; font-size: 0.92rem; line-height: 1.65; }

.jagged-sim-chart { height: 340px; }

.jagged-sim-history table {
    color: #c4d2e6;
    margin: 0;
    font-size: 0.85rem;
}
.jagged-sim-history table th {
    color: #7d90ad;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    border-color: #24314a;
}
.jagged-sim-history table td { border-color: #1d2942; }

.jagged-sim-cm { text-align: center; padding: 8px 4px; }
.jagged-sim-cm-score { font-size: 3rem; font-weight: 800; color: #f5a623; }
.jagged-sim-cm-max { font-size: 1.2rem; color: #8fa3c0; font-weight: 600; }
.jagged-sim-cm-verdict { font-size: 1.15rem; font-weight: 700; color: #38bdf8; margin: 4px 0 10px 0; }
.jagged-sim-cm-kpis { display: flex; justify-content: center; gap: 18px; flex-wrap: wrap; margin-bottom: 12px; }
.jagged-sim-cm-kpi { font-size: 0.9rem; color: #c4d2e6; }
.jagged-sim-cm-kpi strong { color: #eef4fc; }
.jagged-sim-cm-debrief { color: #8fa3c0; font-size: 0.92rem; margin-bottom: 8px; }
.jagged-sim-cm-insights { text-align: left; display: inline-block; color: #c4d2e6; font-size: 0.92rem; margin: 0; padding-left: 20px; }

@media (max-width: 768px) {
    .jagged-sim-container { padding: 12px; }
    .jagged-sim-kpi-grid { grid-template-columns: 1fr 1fr; }
    .jagged-sim-task-row { grid-template-columns: 1fr 1fr; }
    .jagged-sim-task-row .jagged-sim-task-name { grid-column: 1 / -1; }
    .jagged-sim-pipe-row { grid-template-columns: 1fr; }
    .jagged-sim-actions { flex-direction: column; }
    .jagged-sim-chart { height: 260px; }
}

