(function() {
    'use strict';

    class JaggedFrontierAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Jagged Frontier';
            this.version = '1.1.0';

            // Task families at Atlas Advisory Partners. aiq = true AI capability per quarter (index period-1).
            // Deterministic by design: no randomness feeds the score (grading contract).
            this.TASKS = [
                { key: 'market',    hours: 60, blast: 'med',  aiq: [0.94, 0.94, 0.97, 0.97] },
                { key: 'memo',      hours: 25, blast: 'high', aiq: [0.55, 0.55, 0.86, 0.86] },
                { key: 'slides',    hours: 30, blast: 'low',  aiq: [0.90, 0.90, 0.72, 0.72] },
                { key: 'synth',     hours: 40, blast: 'med',  aiq: [0.72, 0.72, 0.95, 0.95] },
                { key: 'audit',     hours: 55, blast: 'high', aiq: [0.60, 0.60, 0.93, 0.93] },
                { key: 'recommend', hours: 45, blast: 'high', aiq: [0.50, 0.50, 0.55, 0.55] }
            ];
            this.BASELINE_HOURS = 255;                  // sum of task hours, all-human
            this.MAX_SAVE = [80, 90, 150, 0];           // efficiency normalizer per quarter
            this.MODE = {
                human:   { cost: 1.00, f: 0    },
                ai:      { cost: 0.15, f: 1.0  },
                centaur: { cost: 0.45, f: 0.5  },
                cyborg:  { cost: 0.60, f: 0.3  }
            };
            this.VER = {
                none: { cost: 0.00, mult: 1.00, humanMult: 1.0 },
                spot: { cost: 0.10, mult: 0.40, humanMult: 0.6 },
                full: { cost: 0.30, mult: 0.08, humanMult: 0.3 }
            };
            this.BLAST_PENALTY = { low: 3, med: 7, high: 14 };
            this.PROBE_HOURS = 3;
            this.CRUNCH_CAP = 165;                      // quarter 2 capacity ceiling
            this.PIPE_STEPS = ['ingest', 'classify', 'analyze', 'draft', 'notify'];
            this.PIPE_REL = { agent: 0.92, checkpoint: 0.995, human: 0.98 };
            this.PIPE_HRS = { agent: 2, checkpoint: 6, human: 14 };
            this.ESC_SCORE = { none: 0, mid: 40, final: 100, both: 85 };
            this.ESC_HRS = { none: 0, mid: 4, final: 4, both: 8 };
        }

        // ---------- helpers ----------

        _t(key, vars) {
            let s = window.mySimulation.t(key);
            if (vars) {
                Object.keys(vars).forEach((k) => {
                    s = s.split('{' + k + '}').join(String(vars[k]));
                });
            }
            return s;
        }

        _clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

        _aiq(task, period) {
            const idx = this._clamp(period - 1, 0, task.aiq.length - 1);
            return task.aiq[idx];
        }

        _taskRisk(task, mode, ver, period) {
            if (mode === 'human') return 0.03 * this.VER[ver].humanMult;
            return (1 - this._aiq(task, period)) * this.MODE[mode].f * this.VER[ver].mult;
        }

        _taskHours(task, mode, ver) {
            return task.hours * (this.MODE[mode].cost + this.VER[ver].cost);
        }

        // Grading contract: single composite formula shared by calculateResults and getPerformanceSummary.
        _composite(ds) {
            const periods = (ds && ds.periods) ? ds.periods : [];
            if (!periods.length) return 0;
            const sum = periods.reduce((s, r) => s + (r && Number.isFinite(r.score) ? r.score : 0), 0);
            return this._clamp(Math.round(sum / periods.length), 0, 100);
        }

        _recomputeAggregates(ds) {
            let trust = 72;
            const effHist = [], trustHist = [];
            ds.periods.forEach((rec) => {
                trust = this._clamp(trust + (rec.trustDelta || 0), 0, 100);
                rec.trust = trust;
                effHist.push(rec.eff);
                trustHist.push(trust);
            });
            ds.trust = trust;
            ds.effHistory = effHist;
            ds.trustHistory = trustHist;
            const last = ds.periods[ds.periods.length - 1];
            ds.lastEff = last ? last.eff : 0;
            ds.lastMap = last ? last.map : 0;
            ds.lastHours = last ? last.hoursUsed : 0;
        }

        // ---------- required methods ----------

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: 72,
                    periods: [],
                    effHistory: [],
                    trustHistory: [],
                    lastEff: 0,
                    lastMap: 0,
                    lastHours: 0,
                    performance: { overallScore: 0 }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const period = state.currentPeriod || 1;
            /* v1.1.0: removed validate-time DOM write (validation is side-effect free; refresh is event-driven). */

            if (period <= 3) {
                const alloc = {};
                let probes = 0;
                for (const task of this.TASKS) {
                    const modeEl = document.getElementById('mode_' + task.key);
                    const verEl = document.getElementById('ver_' + task.key);
                    const probeEl = document.getElementById('probe_' + task.key);
                    const mode = modeEl ? modeEl.value : 'human';
                    const ver = verEl ? verEl.value : 'none';
                    const probe = probeEl ? !!probeEl.checked : false;
                    if (!this.MODE[mode] || !this.VER[ver]) {
                        window.mySimulation.uiManager.showNotification(this._t('warn_invalid'), 'warning');
                        return false;
                    }
                    if (probe) probes++;
                    alloc[task.key] = { mode: mode, ver: ver, probe: probe };
                }
                if (probes > 2) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_probes'), 'warning');
                    return false;
                }
                decisions.alloc = alloc;
                decisions.probes = probes;
            } else {
                const pipe = {};
                for (const step of this.PIPE_STEPS) {
                    const el = document.getElementById('pipe_' + step);
                    const v = el ? el.value : 'agent';
                    if (!this.PIPE_REL[v]) {
                        window.mySimulation.uiManager.showNotification(this._t('warn_invalid'), 'warning');
                        return false;
                    }
                    pipe[step] = v;
                }
                const escEl = document.getElementById('escalationSelect');
                const esc = escEl ? escEl.value : 'none';
                if (this.ESC_SCORE[esc] === undefined) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_invalid'), 'warning');
                    return false;
                }
                decisions.pipe = pipe;
                decisions.escalation = esc;
            }
            return true;
        }

        calculateResults(state) {
            const ds = state.domainState;
            const period = state.currentPeriod || 1;
            const rec = (period <= 3)
                ? this._calcAllocation(state, period)
                : this._calcPipeline(state);

            // Undo-safe: write by index, truncate stale later periods, re-sum everything.
            ds.periods[period - 1] = rec;
            ds.periods.length = period;
            this._recomputeAggregates(ds);

            // GRADING CONTRACT: persist the authoritative 0–100 score every period.
            ds.performance = { overallScore: this._composite(ds) };

            /* v1.1.0: removed racy setTimeout; the briefing/panel now refreshes on the real period:submitted / period:undone events wired in setupUI (fixes undo showing a stale panel). */

            const results = {
                period: period,
                hoursUsed: Math.round(rec.hoursUsed),
                incidents: rec.incidents,
                efficiency: Math.round(rec.eff),
                mapAccuracy: Math.round(rec.map),
                trust: ds.trust,
                overallScore: ds.performance.overallScore,
                score: ds.performance.overallScore
            };
            if (period <= 3) {
                results.delegatedPct = rec.delegatedPct;
            } else {
                results.reliabilityPct = rec.reliabilityPct;
            }
            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('marginDisplay', 'domainState.lastEff', (v) => Math.round(v) + '%');
            uiManager.bind('trustDisplay', 'domainState.trust', (v) => String(Math.round(v)));
            uiManager.bind('mapDisplay', 'domainState.lastMap', (v) => Math.round(v) + '%');
            uiManager.bind('hoursDisplay', 'domainState.lastHours', (v) => Math.round(v) + ' h');

            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        getChartConfig() {
            return {
                frontierChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Delivery efficiency (%)',
                                data: [],
                                borderColor: '#f5a623',
                                backgroundColor: 'rgba(245,166,35,0.10)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.15
                            },
                            {
                                label: 'Client trust',
                                data: [],
                                borderColor: '#38bdf8',
                                backgroundColor: 'rgba(56,189,248,0.08)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.15
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { legend: { labels: { color: '#c4d2e6' } } },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#7d90ad' }, grid: { color: 'rgba(36,49,74,0.6)' } },
                            x: { ticks: { color: '#7d90ad' }, grid: { color: 'rgba(36,49,74,0.4)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = (ds.effHistory || []).map((_, i) => 'Q' + (i + 1));
            return {
                frontierChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.effHistory || [] },
                        { data: ds.trustHistory || [] }
                    ]
                }
            };
        }

        // ---------- period engines ----------

        _calcAllocation(state, period) {
            const ds = state.domainState;
            const alloc = state.decisions.alloc || {};
            let hoursUsed = 0, reworkHours = 0, delegatedHours = 0;
            let incidents = 0;
            let trustDelta = 0;
            let mapPoints = 0;
            const events = [];
            const probes = [];

            for (const task of this.TASKS) {
                const a = alloc[task.key] || { mode: 'human', ver: 'none', probe: false };
                const base = this._taskHours(task, a.mode, a.ver);
                const risk = this._taskRisk(task, a.mode, a.ver, period);
                const rework = risk * task.hours * 2.2;
                hoursUsed += base;
                reworkHours += rework;
                if (a.mode !== 'human') delegatedHours += task.hours;
                if (a.probe) {
                    hoursUsed += this.PROBE_HOURS;
                    probes.push({ task: task.key, round: period, value: this._aiq(task, period) });
                }

                if (risk >= 0.25) {
                    incidents++;
                    trustDelta -= this.BLAST_PENALTY[task.blast];
                    events.push({ code: 'incident', task: task.key });
                } else if (risk >= 0.15 && task.blast === 'high') {
                    trustDelta -= 4;
                    events.push({ code: 'nearmiss', task: task.key });
                }

                mapPoints += this._mapScore(task, a, period);
            }

            hoursUsed += reworkHours;
            let eff = this._clamp((this.BASELINE_HOURS - hoursUsed) / this.MAX_SAVE[period - 1] * 100, 0, 100);
            let deadlineSlip = false;

            if (period === 2 && hoursUsed > this.CRUNCH_CAP) {
                deadlineSlip = true;
                trustDelta -= 10;
                eff = Math.min(eff, 40);
                events.push({ code: 'slip', task: null });
            }
            if (incidents === 0 && !deadlineSlip) {
                trustDelta += 2;
                events.push({ code: 'clean', task: null });
            }

            const map = this._clamp(mapPoints / this.TASKS.length * 100, 0, 100);
            const trustAfter = this._clamp((ds.periods.slice(0, period - 1).reduce((t, r) => this._clamp(t + (r.trustDelta || 0), 0, 100), 72)) + trustDelta, 0, 100);
            const score = this._clamp(Math.round(0.40 * eff + 0.35 * trustAfter + 0.25 * map), 0, 100);

            return {
                kind: 'alloc',
                hoursUsed: hoursUsed,
                delegatedPct: Math.round(delegatedHours / this.BASELINE_HOURS * 100),
                incidents: incidents,
                trustDelta: trustDelta,
                eff: eff,
                map: map,
                score: score,
                deadlineSlip: deadlineSlip,
                events: events,
                probes: probes
            };
        }

        _mapScore(task, a, period) {
            const q = this._aiq(task, period);
            let point;
            if (q >= 0.85) {
                point = (a.mode === 'ai' || a.mode === 'centaur') ? 1.0 : (a.mode === 'cyborg' ? 0.6 : 0.2);
            } else if (q >= 0.65) {
                point = (a.mode === 'centaur' || a.mode === 'cyborg') ? 1.0 : (a.mode === 'human' ? 0.6 : 0.2);
            } else {
                point = (a.mode === 'human') ? 1.0 : (a.mode === 'cyborg' ? 0.7 : (a.mode === 'centaur' ? 0.5 : 0.2));
            }
            const aiInvolved = a.mode !== 'human';
            if (task.blast === 'high' && a.ver === 'none') point *= 0.5;
            if (aiInvolved && q < 0.75 && a.ver !== 'full') point *= 0.5;
            if (a.ver === 'full' && q >= 0.90 && task.blast !== 'high') point *= 0.8;
            // Verification economics: working outside the frontier is legitimate when fully verified.
            if (aiInvolved && q < 0.65 && a.ver === 'full') point = Math.max(point, 0.75);
            return point;
        }

        _calcPipeline(state) {
            const ds = state.domainState;
            const pipe = state.decisions.pipe || {};
            const esc = state.decisions.escalation || 'none';
            let reliability = 1;
            let hours = this.ESC_HRS[esc];
            const events = [];

            for (const step of this.PIPE_STEPS) {
                const choice = this.PIPE_REL[pipe[step]] ? pipe[step] : 'agent';
                reliability *= this.PIPE_REL[choice];
                hours += this.PIPE_HRS[choice];
            }

            const relScore = reliability >= 0.90 ? 100 : reliability / 0.90 * 100;
            const hoursScore = this._clamp((70 - hours) / 60 * 100, 0, 100);
            const escScore = this.ESC_SCORE[esc];
            const score = this._clamp(Math.round(0.55 * relScore + 0.20 * hoursScore + 0.25 * escScore), 0, 100);

            let trustDelta = 0;
            let incidents = 0;
            if (reliability < 0.80) {
                incidents = 1;
                trustDelta = -10;
                events.push({ code: 'pipe_incident', task: null });
            } else if (reliability < 0.90) {
                trustDelta = -4;
                events.push({ code: 'pipe_nearmiss', task: null });
            } else {
                trustDelta = 2;
                events.push({ code: 'pipe_clean', task: null });
            }

            return {
                kind: 'pipeline',
                hoursUsed: hours,
                reliabilityPct: Math.round(reliability * 1000) / 10,
                incidents: incidents,
                trustDelta: trustDelta,
                eff: hoursScore,
                map: escScore,
                score: score,
                deadlineSlip: false,
                events: events,
                probes: []
            };
        }

        // ---------- dynamic UI ----------

        _updateBriefing(state) {
            if (!state) return;
            const period = state.currentPeriod || 1;
            const ds = state.domainState || {};

            const tasksPanel = document.getElementById('tasksPanel');
            const pipePanel = document.getElementById('pipelinePanel');
            if (tasksPanel) tasksPanel.style.display = (period <= 3) ? 'block' : 'none';
            if (pipePanel) pipePanel.style.display = (period >= 4) ? 'block' : 'none';

            const briefEl = document.getElementById('briefingText');
            if (briefEl) {
                const key = 'brief_r' + this._clamp(period, 1, 4);
                briefEl.innerHTML = this._t(key);
            }

            const intelEl = document.getElementById('intelBox');
            if (intelEl) {
                const entries = [];
                (ds.periods || []).forEach((rec) => {
                    (rec.probes || []).forEach((p) => { entries.push(p); });
                });
                if (!entries.length) {
                    intelEl.innerHTML = this._t('intel_none');
                } else {
                    intelEl.innerHTML = entries.map((p) => {
                        const stale = (period >= 3 && p.round < 3);
                        return '🧭 ' + this._t('task_' + p.task) + ': ~' + Math.round(p.value * 100) + '% — '
                            + this._t('intel_probed', { n: p.round })
                            + (stale ? ' · <span class="jagged-sim-stale">' + this._t('intel_stale') + '</span>' : '');
                    }).join('<br>');
                }
            }

            const logEl = document.getElementById('eventLog');
            if (logEl) {
                const last = (ds.periods || [])[Math.min(period, (ds.periods || []).length) - 1];
                if (!last || !last.events || !last.events.length) {
                    logEl.innerHTML = this._t('log_empty');
                } else {
                    logEl.innerHTML = last.events.map((e) => {
                        if (e.code === 'incident') return '🔴 ' + this._t('task_' + e.task) + ' — ' + this._t('incident_line');
                        if (e.code === 'nearmiss') return '🟠 ' + this._t('task_' + e.task) + ' — ' + this._t('nearmiss_line');
                        if (e.code === 'slip') return '⏰ ' + this._t('slip_line');
                        if (e.code === 'clean') return '🟢 ' + this._t('clean_line');
                        if (e.code === 'pipe_incident') return '🔴 ' + this._t('pipe_incident_line');
                        if (e.code === 'pipe_nearmiss') return '🟠 ' + this._t('pipe_nearmiss_line');
                        return '🟢 ' + this._t('pipe_clean_line');
                    }).join('<br>');
                }
            }
        }

        // ---------- summary, debrief, hints ----------

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const composite = this._composite(ds);

            let performance = 'Beginner';
            if (composite >= 55) performance = 'Good';
            if (composite >= 75) performance = 'Excellent';

            const totalIncidents = (ds.periods || []).reduce((s, r) => s + (r.incidents || 0), 0);
            const avgEff = (ds.periods || []).length
                ? Math.round((ds.periods.reduce((s, r) => s + (r.eff || 0), 0)) / ds.periods.length) : 0;
            const avgMap = (ds.periods || []).length
                ? Math.round((ds.periods.reduce((s, r) => s + (r.map || 0), 0)) / ds.periods.length) : 0;

            const insights = [];
            if (avgMap >= 70) insights.push(this._t('insight_map_good')); else insights.push(this._t('insight_map_weak'));
            if (totalIncidents === 0) insights.push(this._t('insight_quality_good')); else insights.push(this._t('insight_quality_weak'));
            if (avgEff >= 60) insights.push(this._t('insight_econ_good')); else insights.push(this._t('insight_econ_weak'));
            insights.push(this._t('insight_frontier'));

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performance: performance,
                performanceLabel: this._t('grade_' + performance.toLowerCase()),
                avgEfficiency: avgEff,
                finalTrust: ds.trust,
                avgMapAccuracy: avgMap,
                totalIncidents: totalIncidents,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            const items = (s.insights || []).map((t) => '<li>' + t + '</li>').join('');
            return '<div class="jagged-sim-cm">'
                + '<div class="jagged-sim-cm-score">' + score + '<span class="jagged-sim-cm-max">/100</span></div>'
                + '<div class="jagged-sim-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="jagged-sim-cm-kpis">'
                + '<span class="jagged-sim-cm-kpi">' + this._t('cm_margin') + ': <strong>' + (s.avgEfficiency || 0) + '%</strong></span>'
                + '<span class="jagged-sim-cm-kpi">' + this._t('cm_trust') + ': <strong>' + (s.finalTrust || 0) + '</strong></span>'
                + '<span class="jagged-sim-cm-kpi">' + this._t('cm_map') + ': <strong>' + (s.avgMapAccuracy || 0) + '%</strong></span>'
                + '<span class="jagged-sim-cm-kpi">' + this._t('cm_incidents') + ': <strong>' + (s.totalIncidents || 0) + '</strong></span>'
                + '</div>'
                + '<div class="jagged-sim-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="jagged-sim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.incidents > 0) return this._t('hint_verify');
            const rec = state.domainState.periods[(results.period || 1) - 1];
            if (rec && rec.deadlineSlip) return this._t('hint_delegate');
            if (results.period === 3 && results.efficiency < 50) return this._t('hint_remap');
            if (results.period === 3) return this._t('hint_pipeline');
            return null;
        }

